    if (existing && !episode.fromShowLink) return { file: existing, episode };
    const title = episode.title || t("\u672A\u547D\u540D\u5355\u96C6");
    const safeTitle = title.replace(/[\\/:*?"<>|#^[\]]/g, "-").slice(0, 100).trim() || t("\u672A\u547D\u540D\u5355\u96C6");
